+// API keys and roles: who is calling, and what their role may do.
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+const ROLES = ["viewer", "cook", "manager"];
+
+// Beyond reading, a cook may do these. Any other route that is not a GET is
+// for managers only, so a new route is closed until it is listed here.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Reads that are for managers only.
+const MANAGER_READS = new Set(["GET /audit"]);
+
+const digest = (text) => createHash("sha256").update(text).digest();
+
+/** The API key record for `key`, or AppError unauthorized. */
+export function authenticate(store, key) {
+  const wanted = digest(key);
+  const found = store.data.apiKeys.find((k) => typeof k.key === "string" && timingSafeEqual(digest(k.key), wanted));
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Whether `role` may call the route `method pattern`. */
+export function canAccess(role, method, pattern) {
+  if (!ROLES.includes(role)) return false;
+  if (role === "manager") return true;
+  const route = `${method} ${pattern}`;
+  if (method === "GET") return !MANAGER_READS.has(route);
+  return role === "cook" && COOK_ROUTES.has(route);
+}
+
+/** Throws AppError forbidden unless `role` may call the route. */
+export function requireAccess(role, method, pattern) {
+  if (!canAccess(role, method, pattern)) throw new AppError("forbidden");
+}
